import { useLayoutEffect, useState, useCallback } from "react";
import { debounce } from "lodash-es";

export const useOverflowBreadcrumbs = (
  containerRef: React.RefObject<HTMLElement>, // the <ol> element
  overflowButtonRef: React.RefObject<HTMLElement>,
  middleItemCount: number,
  mode: "collapse" | "gradual",
  rootRef: React.RefObject<HTMLElement>,
) => {
  const [visibleMiddleCount, setVisibleMiddleCount] = useState<number>(Infinity);

  const measure = useCallback(() => {
    const container = containerRef.current;
    if (!container || !rootRef.current || middleItemCount === 0) {
      setVisibleMiddleCount(Infinity);
      return;
    }

    const containerWidth = rootRef.current.offsetWidth;
    const gap = parseFloat(window.getComputedStyle(container).gap) || 0;

    const firstItem = container.querySelector<HTMLElement>("[data-breadcrumb-index='first']");
    const lastItem = container.querySelector<HTMLElement>("[data-breadcrumb-index='last']");
    const overflowButton = overflowButtonRef.current;

    // Get all middle items and dividers
    const middleItems = Array.from(
      container.querySelectorAll<HTMLElement>(
        "[data-breadcrumb-index]:not([data-breadcrumb-index='first']):not([data-breadcrumb-index='last'])",
      ),
    );
    const dividers = Array.from(
      container.querySelectorAll<HTMLElement>("[data-breadcrumb-divider]"),
    );

    const getWidth = (el: HTMLElement | null) => el?.getBoundingClientRect().width ?? 0;

    const firstWidth = getWidth(firstItem);
    const lastWidth = getWidth(lastItem);
    const overflowWidth = getWidth(overflowButton);

    // Calculate total width of all items and dividers as if they were all visible
    let totalFullWidth = firstWidth + lastWidth;
    middleItems.forEach((item) => {
      totalFullWidth += getWidth(item) + gap;
    });
    dividers.forEach((divider) => {
      totalFullWidth += getWidth(divider) + gap;
    });

    // Check if everything fits
    if (totalFullWidth <= containerWidth) {
      setVisibleMiddleCount(Infinity);
      return;
    }

    if (mode === "collapse") {
      setVisibleMiddleCount(0);
      return;
    }

    // mode === 'gradual'
    // In gradual mode, we always have First + Divider + Overflow + Divider + Last
    // We want to see how many middle items we can fit.

    // Base width: First + Divider + Overflow + Divider + Last
    // The number of dividers when some items are hidden:
    // 1 (after first) + 1 (after overflow) + 1 (before last) = 3
    // But we also need dividers between visible middle items.

    const dividerWidth = dividers.length > 0 ? getWidth(dividers[0]) : 0;

    let currentWidth =
      firstWidth + gap + dividerWidth + gap + overflowWidth + gap + dividerWidth + gap + lastWidth;
    let count = 0;

    for (let i = 0; i < middleItems.length; i++) {
      const itemWidth = getWidth(middleItems[i]);
      // If we add this item, we also add a divider
      if (currentWidth + itemWidth + gap + dividerWidth > containerWidth) {
        break;
      }
      currentWidth += itemWidth + gap + dividerWidth;
      count++;
    }

    setVisibleMiddleCount(count);
  }, [containerRef, rootRef, middleItemCount, overflowButtonRef, mode]);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const root = rootRef.current;
    if (!container || !root) return;

    const debouncedMeasure = debounce(measure, 0);
    const observer = new ResizeObserver(debouncedMeasure);

    observer.observe(root);
    if (overflowButtonRef.current) {
      observer.observe(overflowButtonRef.current);
    }

    // Initial measure
    debouncedMeasure();

    return () => {
      observer.disconnect();
    };
  }, [measure, containerRef, rootRef, overflowButtonRef]);

  return { visibleMiddleCount };
};
